package com.trainflow.trainingcase; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="training_catalog_items") public class TrainingCatalogItem { @Id @JdbcTypeCode(SqlTypes.VARCHAR) @Column(columnDefinition="char(36)") private UUID id; @Column(nullable=false,length=100) private String category; @Column(nullable=false,length=250) private String title; @Column(name="is_active",nullable=false) private boolean active; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; protected TrainingCatalogItem(){} public UUID getId(){return id;} public String getCategory(){return category;} public String getTitle(){return title;} public boolean isActive(){return active;} }
